128	    const countQuery = itemsQuery.clone().count('*', { as: 'count' });
129	
130	    itemsQuery = itemsQuery.orderBy('id', 'asc');
131	    if (options.afterId !== undefined) {
132	      itemsQuery = itemsQuery.where('id', '>', options.afterId);
133	    }
134	    if (options.limit !== undefined) {
135	      itemsQuery = itemsQuery.limit(options.limit);
136	    }
137	
138	    const [items, [{ count }]] = await Promise.all([itemsQuery, countQuery]);
